import React, { useState } from "react";
import Navbar from "../components/Navbar";
import { api } from "../utils/api";

export default function Signup() {
  const [loading, setLoading] = useState(false);

  const [form, setForm] = useState({
    name: "",
    email: "",
    password: ""
  });

  async function submit(e) {
    e.preventDefault();
    setLoading(true);

    try {
      const res = await api.post("/api/user/signup", form);

      localStorage.setItem("user_token", res.data.token);
      localStorage.setItem("user_profile", JSON.stringify(res.data.user));

      window.location.href = "/portal";
    } catch (err) {
      alert(err?.response?.data?.message || "Signup failed");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <Navbar />

      <div className="max-w-lg mx-auto px-4 py-12">
        <h1 className="text-4xl font-black">Create Account</h1>
        <p className="text-gray-600 mt-2">
          Sign up to track your scam reports & SOC replies.
        </p>

        <form
          onSubmit={submit}
          className="mt-8 bg-white rounded-3xl shadow p-6 space-y-4"
        >
          <input
            className="w-full border rounded-2xl px-4 py-3"
            placeholder="Full Name"
            value={form.name}
            onChange={(e) => setForm({ ...form, name: e.target.value })}
          />

          <input
            className="w-full border rounded-2xl px-4 py-3"
            placeholder="Email"
            type="email"
            value={form.email}
            onChange={(e) => setForm({ ...form, email: e.target.value })}
          />

          <input
            className="w-full border rounded-2xl px-4 py-3"
            placeholder="Password (min 6)"
            type="password"
            value={form.password}
            onChange={(e) => setForm({ ...form, password: e.target.value })}
          />

          <button
            disabled={loading}
            className="w-full px-6 py-3 rounded-2xl bg-gray-900 text-white font-semibold"
          >
            {loading ? "Creating..." : "Signup"}
          </button>

          <p className="text-sm text-gray-600 text-center">
            Already have account?{" "}
            <a href="/login" className="text-blue-600 underline">
              Login
            </a>
          </p>
        </form>
      </div>
    </div>
  );
}
